def validate_params(cls, sampling_params: SamplingParams) -> None:
        """Check the ``dry_*`` keys of ``extra_args`` at request admission.

        Raises:
            ValueError: on an unknown or out-of-range DRY argument.

        """
        extra = sampling_params.extra_args or {}
        unknown = sorted(
            key for key in extra if key.startswith("dry_") and key not in _DRY_DEFAULTS
        )
        if unknown:
            # A misspelled key would otherwise be ignored silently.
            raise ValueError(
                f"Unknown dry_* extra_args: {', '.join(unknown)}. "
                f"Supported keys: {', '.join(_DRY_DEFAULTS)}."
            )

        args = _dry_args(sampling_params)
        for name in (
            "dry_multiplier",
            "dry_base",
            "dry_allowed_length",
            "dry_penalty_last_n",
        ):
            value = args[name]
            # JSON true/false are bools, which pass isinstance(value, int).
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"{name} must be a number, got {type(value).__name__}."
                )

        multiplier = args["dry_multiplier"]
        base = args["dry_base"]
        allowed_length = args["dry_allowed_length"]
        penalty_last_n = args["dry_penalty_last_n"]
        breakers = args["dry_sequence_breakers"]

        if not math.isfinite(multiplier) or multiplier < 0.0:
            raise ValueError(
                f"dry_multiplier must be non-negative and finite, got {multiplier}."
            )
        if not math.isfinite(base) or base < 0.0:
            raise ValueError(f"dry_base must be non-negative and finite, got {base}.")
        if (
            not isinstance(allowed_length, int)
            or allowed_length < 0
            or allowed_length > _DRY_INT_MAX
        ):
            raise ValueError(
                f"dry_allowed_length must be an integer in [0, {_DRY_INT_MAX}], "
                f"got {allowed_length}."
            )
        if (
            not isinstance(penalty_last_n, int)
            or penalty_last_n < -1
            or penalty_last_n > _DRY_INT_MAX
        ):
            raise ValueError(
                "dry_penalty_last_n must be an integer: -1 (whole context), "
                f"0 (disable), or in [1, {_DRY_INT_MAX}], got {penalty_last_n}."
            )
        if not isinstance(breakers, (list, tuple)) or any(
            not isinstance(s, str) for s in breakers
        ):
            raise ValueError(
                f"dry_sequence_breakers must be a list of strings, got {breakers!r}."
            )
        if len(breakers) > MAX_DRY_SEQUENCE_BREAKERS:
            raise ValueError(
                f"dry_sequence_breakers supports at most "
                f"{MAX_DRY_SEQUENCE_BREAKERS} entries, got {len(breakers)}."
            )
        if multiplier and 0.0 <= base < 1.0:
            # libllama has the same gate. llama-server resets such a base to its
            # default instead.
            logger.warning(
                "dry_base=%s is below 1.0, which disables DRY entirely "
                "(llama.cpp semantics), even though dry_multiplier=%s was "
                "set. No repetition penalty will be applied.",
                base,
                multiplier,
            )

def _vocab_index(tokenizer: Any) -> _VocabIndex:
    """Decode every token of ``tokenizer`` once and index its characters."""
    index = _vocab_index_cache.get(tokenizer)
    if index is None:
        # Include added tokens above vocab_size, which llama.cpp's scan also covers.
        n_ids = getattr(tokenizer, "max_token_id", tokenizer.vocab_size - 1) + 1
        texts = tokenizer.batch_decode([[i] for i in range(n_ids)])
        char_ids: dict[str, list[int]] = {}
        for i, text in enumerate(texts):
            for char in set(text):
                char_ids.setdefault(char, []).append(i)
        index = _VocabIndex(texts, char_ids)
        _vocab_index_cache[tokenizer] = index
    return index

def resolve_dry_breakers(tokenizer: Any, breaker_strs: tuple[str, ...]) -> list[int]:
    """Resolve breaker strings to the ids of every token whose text contains one.

    This is llama.cpp's ``get_overlapping_token_sequences`` rule, without its
    multi-token restart sequences. Resolution runs in ``add_request``, inside
    ``execute_model``, so a single-character breaker (llama.cpp's defaults and
    most custom sets) resolves by lookup in the character index instead of a
    vocabulary scan. Results are cached per (tokenizer, breaker set).
    """
    breaker_strs = tuple(s[:_MAX_BREAKER_CHAR_LEN] for s in breaker_strs if s)
    if not breaker_strs:
        return []
    per_tok = _breaker_ids_cache.setdefault(tokenizer, {})
    cached = per_tok.get(breaker_strs)
    if cached is not None:
        return list(cached)

    index = _vocab_index(tokenizer)
    ids: set[int] = set()
    for s in breaker_strs:
        if len(s) == 1:
            ids.update(index.char_ids.get(s, ()))
        else:
            ids.update(i for i, text in enumerate(index.texts) if s in text)
    result = sorted(ids)
    if len(per_tok) >= _MAX_CACHED_BREAKER_SETS:
        # Evict the oldest entry (dict preserves insertion order).
        per_tok.pop(next(iter(per_tok)))
    per_tok[breaker_strs] = result
    return list(result)

def max_exponent(base: float) -> int:
    """Exponent clamp, mirroring llama.cpp bit-for-bit.

    llama.cpp computes ``FLOAT_MAX_LOG / std::log(dry_base)`` entirely in
    float32. Computing the quotient in float64 lands on the wrong side of
    the integer truncation for some bases: at ``base=2.0`` float64 gives
    127.99999998 -> 127 while float32 gives exactly 128.0 -> 128.
    """
    if base <= 1.000001:
        return 0
    return int(np.float32(_FLOAT_MAX_LOG) / np.log(np.float32(base)))

def __init__(
        self,
        logprobs_mode: LogprobsMode = "raw_logprobs",
        use_fp64_gumbel: bool = False,
    ) -> None:
        super().__init__()
        self.logprobs_mode = logprobs_mode
        self.use_fp64_gumbel = use_fp64_gumbel
        if current_platform.is_cuda():
            # FlashInfer doesn't expose post-top-k/top-p logits/logprobs,
            # so it can't be used when the configured mode requires them.
            can_use_flashinfer = (
                logprobs_mode not in PROCESSED_LOGPROBS_MODES
                and flashinfer_sampler_supported()
            )
            self.forward = (
                self.forward_cuda if can_use_flashinfer else self.forward_native
            )
        elif current_platform.is_cpu():
            arch = current_platform.get_cpu_architecture()
            # Fall back to native implementation for POWERPC and RISCV.
            # On PowerPC argmax produces incorrect output with torch.compile.
            # PR: https://github.com/vllm-project/vllm/pull/26987
            if arch in (CpuArchEnum.RISCV, CpuArchEnum.POWERPC):
                self.forward = self.forward_native
            else:
                self.forward = self.forward_cpu
        elif current_platform.is_xpu():
            if xpu_sampler_supported() and not envs.VLLM_BATCH_INVARIANT:
                self.forward = self.forward_xpu
            else:
                if envs.VLLM_BATCH_INVARIANT:
                    logger.info_once(
                        "VLLM_BATCH_INVARIANT is enabled. Using the "
                        "PyTorch-native sampler on XPU."
                    )
                self.forward = self.forward_native
        elif (
            logprobs_mode not in PROCESSED_LOGPROBS_MODES
            and rocm_aiter_ops.is_enabled()
        ):
            # Lazy ROCm-only import; keeps arch detection out of import time
            # on CUDA/CPU.
            from vllm.platforms.rocm import on_gfx1250

            self.on_gfx1250 = on_gfx1250()
            self.aiter_ops = None
            self._aiter_ops_import_failed = False
            logger.info_once(
                "Using aiter sampler on ROCm (lazy import, sampling-only)."
            )
            self.forward = self.forward_hip
        else:
            self.forward = self.forward_native

        # Every accelerator backend can fall back to native sampling at runtime.
        register_top_k_top_p_warmups()

def forward_hip(
        self,
        logits: torch.Tensor,
        generators: dict[int, torch.Generator],
        k: torch.Tensor | None,
        p: torch.Tensor | None,
    ) -> tuple[torch.Tensor, torch.Tensor | None]:
        """Optimized ROCm/aiter path."""
        if self.on_gfx1250:
            if (
                k is None
                and p is None
                and not self.use_fp64_gumbel
                and self.logprobs_mode not in PROCESSED_LOGPROBS_MODES
            ):
                return _aiter_temp_gumbel_sample(logits, generators), None
            return self.forward_native(logits, generators, k, p)
        if (k is None and p is None) or generators:
            if generators:
                logger.warning_once(
                    "aiter sampler does not support per-request generators; "
                    "falling back to PyTorch-native."
                )
            return self.forward_native(logits, generators, k, p)
        if self.use_fp64_gumbel:
            return self.forward_native(logits, generators, k, p)
        assert self.logprobs_mode not in PROCESSED_LOGPROBS_MODES, (
            "aiter sampler does not support returning logits/logprobs."
        )
        if self.aiter_ops is None and not self._init_aiter_ops():
            return self.forward_native(logits, generators, k, p)
        try:
            return self.aiter_sample(logits, k, p, generators), None
        except (ImportError, OSError, RuntimeError, CalledProcessError) as err:
            # Some AITER wheels expose the op before its JIT extension exists.
            self._aiter_ops_import_failed = True
            self.forward = self.forward_native
            logger.warning_once(
                "AITER sampling kernel is unavailable on this ROCm system "
                "(%s). Falling back to PyTorch-native sampling.",
                err,
            )
            return self.forward_native(logits, generators, k, p)

def _load_v2_logitsprocs_by_fqcns(
    logits_processors: Sequence[str | type],
) -> list[type[LogitsProcessor]]:
    """Resolve a mixed list of processor types and FQCN strings into types.

    FQCN syntax is <module>:<type> i.e. x.y.z:CustomLogitProc.
    """
    from vllm.utils.torch_utils import guard_cuda_initialization

    classes: list[type[LogitsProcessor]] = []
    for ldx, logitproc in enumerate(logits_processors):
        if isinstance(logitproc, type):
            logger.debug(" - Already-loaded logit processor: %s", logitproc.__name__)
            if not issubclass(logitproc, LogitsProcessor):
                raise ValueError(
                    f"{logitproc.__name__} is not a subclass of "
                    "vllm.v1.worker.gpu.sample.logits_processor.LogitsProcessor"
                )
            classes.append(logitproc)
            continue

        logger.debug("- Loading logits processor %s", logitproc)
        parts = logitproc.split(":")
        if len(parts) != 2:
            raise ValueError(
                f"Invalid logits processor FQCN {logitproc!r}. "
                "Expected format: '<module>:<type>'"
            )
        module_path, qualname = parts

        try:
            with guard_cuda_initialization():
                module = importlib.import_module(module_path)
        except Exception as e:
            logger.error(
                "Failed to load %sth LogitsProcessor plugin %s: %s",
                ldx,
                logitproc,
                e,
            )
            raise RuntimeError(
                f"Failed to load {ldx}th LogitsProcessor plugin {logitproc}"
            ) from e

        obj = module
        for attr in qualname.split("."):
            obj = getattr(obj, attr)
        if not isinstance(obj, type):
            raise ValueError("Loaded logit processor must be a type.")
        if not issubclass(obj, LogitsProcessor):
            raise ValueError(
                f"{obj.__name__} is not a subclass of "
                "vllm.v1.worker.gpu.sample.logits_processor.LogitsProcessor"
            )
        classes.append(obj)

    return classes

def build_custom_logits_processors_params_validator(
    custom_logitsprocs: Sequence[str | type] | None,
) -> "Callable[[SamplingParams], None]":
    """Load custom processor classes once and return a params validator.

    Called from the frontend at startup. The returned callable runs each
    processor's ``validate_params`` at request admission.

    Raises:
        ValueError: if a loaded class does not implement the V2 interface.
        RuntimeError: if an FQCN fails to import.

    """
    classes = _cached_load_v2_logitsprocs(tuple(custom_logitsprocs or ()))

    if not classes:
        return lambda _: None

    def validate_params(sampling_params: "SamplingParams") -> None:
        for cls in classes:
            try:
                cls.validate_params(sampling_params)
            except ValueError as e:
                raise VLLMValidationError(str(e)) from e

    return validate_params
